// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title KIMI
/// @notice Platform utility token for the Kimi AI deployer.
///         Users burn KIMI to pay for contract deployment fees.
contract KIMI is ERC20, ERC20Burnable, Ownable {
    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply
    ) ERC20(name, symbol) Ownable(msg.sender) {
        require(bytes(name).length != 0, "KIMI_NAME_EMPTY");
        require(bytes(symbol).length != 0, "KIMI_SYMBOL_EMPTY");
        require(initialSupply != 0, "KIMI_SUPPLY_ZERO");
        _mint(msg.sender, initialSupply);
    }

    /// @notice Allows the owner to mint additional KIMI.
    /// @dev Use with caution; intended for liquidity bootstrapping only.
    function mint(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "KIMI_TO_ZERO");
        require(amount != 0, "KIMI_AMOUNT_ZERO");
        _mint(to, amount);
    }
}

contracts/FixedSupplyToken.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/// @title FixedSupplyToken
/// @notice A standard 18-decimal ERC20 with a fixed initial supply and holder burns.
contract FixedSupplyToken is ERC20, ERC20Burnable {
    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply
    ) ERC20(name, symbol) {
        require(bytes(name).length != 0, "TOKEN_NAME_EMPTY");
        require(bytes(symbol).length != 0, "TOKEN_SYMBOL_EMPTY");
        require(initialSupply != 0, "TOKEN_SUPPLY_ZERO");
        require(initialSupply <= type(uint256).max / (10 ** uint256(decimals())), "TOKEN_SUPPLY_TOO_LARGE");
        _mint(msg.sender, initialSupply * (10 ** uint256(decimals())));
    }
}

contracts/mint/KimiMintLaunchFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { KimiMintToken } from "./KimiMintToken.sol";
import { KimiMintVault } from "./KimiMintVault.sol";

interface IKimiMintTokenDeployer {
    function deploy(
        KimiMintToken.LaunchConfig calldata launchConfig,
        KimiMintToken.TaxConfig calldata taxConfig,
        address initialHolder,
        bytes32 salt
    )
        external
        returns (address token);
}

interface IKimiMintVaultDeployer {
    function deploy(
        address token,
        address liquidityRouter,
        address paymentToken,
        address owner,
        address receiver,
        uint256 totalSupply,
        uint256 totalMints,
        uint256 mintPrice,
        uint256 maxMintPerWallet,
        uint256 whitelistMintLimit,
        bool whitelistEnabled,
        bytes32 salt
    )
        external
        returns (address vault);
}

interface IKimiMintLaunchRouter {
    function WETH() external view returns (address);
    function factory() external view returns (address);
}

interface IKimiMintLaunchSwapFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

contract KimiMintLaunchFactory is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    uint16 public constant BPS_DENOMINATOR = 10_000;
    uint16 public constant MAX_TAX_BPS = 2_500;
    address public constant DEFAULT_REWARD_TOKEN = 0x55d398326f99059fF775485246999027B3197955;

    uint256 public creationFee;
    address public feeRecipient;
    address public creationFeeToken;
    uint256 public creationFeeAmount;
    address public liquidityRouter;
    address public tokenDeployer;
    address public vaultDeployer;
    uint16 public immutable requiredTokenSuffix;
    address[] public allTokens;

    struct LaunchParams {
        string name;
        string symbol;
        string metadataUri;
        uint256 totalSupply;
        uint256 mintCount;
        uint256 mintPrice;
        uint256 maxMintPerWallet;
        address paymentToken;
        address rewardToken;
        uint256 rewardThreshold;
        address receiver;
        bytes32 templateId;
        uint16 buyTaxBps;
        uint16 sellTaxBps;
        uint16 transferTaxBps;
        uint16 addLiquidityTaxBps;
        uint16 removeLiquidityTaxBps;
        uint16 launchProtectionTaxBps;
        uint16 launchProtectionBlocks;
        uint32 claimWait;
        uint16 fundFeeBps;
        uint16 lpFeeBps;
        uint16 dividendFeeBps;
        uint16 burnFeeBps;
        uint256 whitelistMintCount;
        bool whitelistEnabled;
    }

    struct Project {
        address creator;
        address token;
        address vault;
        address paymentToken;
        address receiver;
        address platformFeeReceiver;
        bytes32 templateId;
        uint256 totalSupply;
        uint256 mintCount;
        uint256 whitelistMintCount;
        uint256 publicMintCount;
        uint256 mintPrice;
        uint256 maxMintPerWallet;
        bool whitelistEnabled;
        string metadataUri;
        uint64 createdAt;
        address rewardToken;
        uint256 rewardThreshold;
        uint16 buyTaxBps;
        uint16 sellTaxBps;
        uint16 transferTaxBps;
        uint16 addLiquidityTaxBps;
        uint16 removeLiquidityTaxBps;
        uint16 launchProtectionTaxBps;
        uint16 launchProtectionBlocks;
        uint32 claimWait;
        uint16 fundFeeBps;
        uint16 lpFeeBps;
        uint16 dividendFeeBps;
        uint16 burnFeeBps;
    }

    mapping(address token => Project project) public projects;
    mapping(address creator => address[] tokens) private _creatorTokens;
    mapping(bytes32 templateId => address[] tokens) private _templateTokens;

    error InvalidFee();
    error InvalidParams();
    error InvalidTokenSuffix(address token, uint16 requiredSuffix);
    error ZeroAddress();

    event LaunchCreated(
        address indexed creator,
        address indexed token,
        address indexed vault,
        bytes32 templateId,
        string name,
        string symbol,
        uint256 totalSupply,
        uint256 mintCount,
        uint256 mintPrice,
        address paymentToken,
        bool whitelistEnabled,
        string metadataUri
    );
    event CreationFeeUpdated(uint256 creationFee);
    event FeeRecipientUpdated(address indexed feeRecipient);
    event ProjectIndexed(
        address indexed creator,
        bytes32 indexed templateId,
        address indexed token,
        address vault
    );

    constructor(
        address feeRecipient_,
        uint256 creationFee_,
        address creationFeeToken_,
        uint256 creationFeeAmount_,
        address liquidityRouter_,
        address tokenDeployer_,
        address vaultDeployer_,
        uint16 requiredTokenSuffix_
    )
        Ownable(msg.sender)
    {
        if (
            feeRecipient_ == address(0) || liquidityRouter_ == address(0)
                || tokenDeployer_ == address(0) || vaultDeployer_ == address(0)
        ) {
            revert ZeroAddress();
        }

        feeRecipient = feeRecipient_;
        creationFeeToken = creationFeeToken_;
        creationFeeAmount = creationFeeAmount_;
        liquidityRouter = liquidityRouter_;
        tokenDeployer = tokenDeployer_;
        vaultDeployer = vaultDeployer_;
        creationFee = creationFee_;
        requiredTokenSuffix = requiredTokenSuffix_;
    }

    function createLaunch(LaunchParams calldata params, bytes32 salt)
        external
        payable
        nonReentrant
        returns (address token, address vault)
    {
        _validateParams(params);
        _collectCreationFee();

        bytes32 tokenSalt = keccak256(
            abi.encodePacked(msg.sender, salt, params.name, params.symbol, block.chainid)
        );
        address rewardToken = params.rewardToken == address(0)
            ? DEFAULT_REWARD_TOKEN
            : params.rewardToken;

        KimiMintToken launchToken = KimiMintToken(payable(IKimiMintTokenDeployer(tokenDeployer).deploy(
            KimiMintToken.LaunchConfig({
                name: params.name,
                symbol: params.symbol,
                projectUri: params.metadataUri,
                templateId: params.templateId,
                receiver: params.receiver,
                platformFeeReceiver: feeRecipient,
                paymentToken: params.paymentToken,
                rewardToken: rewardToken,
                rewardThreshold: params.rewardThreshold,
                totalSupply: params.totalSupply
            }),
            KimiMintToken.TaxConfig({
                buyTaxBps: params.buyTaxBps,
                sellTaxBps: params.sellTaxBps,
                transferTaxBps: params.transferTaxBps,
                addLiquidityTaxBps: params.addLiquidityTaxBps,
                removeLiquidityTaxBps: params.removeLiquidityTaxBps,
                launchProtectionTaxBps: params.launchProtectionTaxBps,
                launchProtectionBlocks: params.launchProtectionBlocks,
                claimWait: params.claimWait,
                fundFeeBps: params.fundFeeBps,
                lpFeeBps: params.lpFeeBps,
                dividendFeeBps: params.dividendFeeBps,
                burnFeeBps: params.burnFeeBps
            }),
            address(this),
            tokenSalt
        )));

        launchToken.setLiquidityRouter(liquidityRouter);
        _requireTokenSuffix(address(launchToken));
        address launchPair = _createLaunchPair(address(launchToken));
        launchToken.setLaunchPair(launchPair);

        KimiMintVault mintVault = KimiMintVault(payable(IKimiMintVaultDeployer(vaultDeployer).deploy(
            address(launchToken),
            liquidityRouter,
            params.paymentToken,
            msg.sender,
            params.receiver,
            params.totalSupply,
            params.mintCount,
            params.mintPrice,
            params.maxMintPerWallet,
            params.whitelistMintCount,
            params.whitelistEnabled,
            keccak256(abi.encodePacked(tokenSalt, "VAULT"))
        )));

        token = address(launchToken);
        vault = address(mintVault);

        launchToken.setLaunchVault(vault);
        launchToken.transfer(vault, params.totalSupply);
        launchToken.transferOwnership(msg.sender);

        projects[token] = Project({
            creator: msg.sender,
            token: token,
            vault: vault,
            paymentToken: params.paymentToken,
            receiver: params.receiver,
            platformFeeReceiver: feeRecipient,
            templateId: params.templateId,
            totalSupply: params.totalSupply,
            mintCount: params.mintCount,
            whitelistMintCount: params.whitelistMintCount,
            publicMintCount: params.mintCount - params.whitelistMintCount,
            mintPrice: params.mintPrice,
            maxMintPerWallet: params.maxMintPerWallet,
            whitelistEnabled: params.whitelistEnabled,
            metadataUri: params.metadataUri,
            createdAt: uint64(block.timestamp),
            rewardToken: rewardToken,
            rewardThreshold: params.rewardThreshold,
            buyTaxBps: params.buyTaxBps,
            sellTaxBps: params.sellTaxBps,
            transferTaxBps: params.transferTaxBps,
            addLiquidityTaxBps: params.addLiquidityTaxBps,
            removeLiquidityTaxBps: params.removeLiquidityTaxBps,
            launchProtectionTaxBps: params.launchProtectionTaxBps,
            launchProtectionBlocks: params.launchProtectionBlocks,
            claimWait: params.claimWait,
            fundFeeBps: params.fundFeeBps,
            lpFeeBps: params.lpFeeBps,
            dividendFeeBps: params.dividendFeeBps,
            burnFeeBps: params.burnFeeBps
        });
        allTokens.push(token);
        _creatorTokens[msg.sender].push(token);
        _templateTokens[params.templateId].push(token);

        emit LaunchCreated(
            msg.sender,
            token,
            vault,
            params.templateId,
            params.name,
            params.symbol,
            params.totalSupply,
            params.mintCount,
            params.mintPrice,
            params.paymentToken,
            params.whitelistEnabled,
            params.metadataUri
        );
        emit ProjectIndexed(msg.sender, params.templateId, token, vault);
    }

    function allTokensLength() external view returns (uint256) {
        return allTokens.length;
    }

    function creatorTokensLength(address creator) external view returns (uint256) {
        return _creatorTokens[creator].length;
    }

    function creatorTokenAt(address creator, uint256 index) external view returns (address) {
        return _creatorTokens[creator][index];
    }

    function templateTokensLength(bytes32 templateId) external view returns (uint256) {
        return _templateTokens[templateId].length;
    }

    function templateTokenAt(bytes32 templateId, uint256 index) external view returns (address) {
        return _templateTokens[templateId][index];
    }

    function getProject(address token) external view returns (Project memory) {
        return projects[token];
    }

    function getProjects(uint256 offset, uint256 limit) external view returns (Project[] memory items) {
        uint256 length = allTokens.length;
        if (offset >= length || limit == 0) {
            return new Project[](0);
        }

        uint256 end = offset + limit;
        if (end > length || end < offset) {
            end = length;
        }

        items = new Project[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            items[i - offset] = projects[allTokens[i]];
        }
    }

    function setCreationFee(uint256 nextFee) external onlyOwner {
        creationFee = nextFee;
        emit CreationFeeUpdated(nextFee);
    }

    function setFeeRecipient(address nextFeeRecipient) external onlyOwner {
        if (nextFeeRecipient == address(0)) {
            revert ZeroAddress();
        }

        feeRecipient = nextFeeRecipient;
        emit FeeRecipientUpdated(nextFeeRecipient);
    }

    function _validateParams(LaunchParams calldata params) private pure {
        if (
            bytes(params.name).length == 0 || bytes(params.symbol).length == 0
                || params.totalSupply == 0 || params.mintCount == 0 || params.receiver == address(0)
                || params.mintPrice == 0 || params.totalSupply < params.mintCount
                || params.whitelistMintCount > params.mintCount || params.paymentToken != address(0)
        ) {
            revert InvalidParams();
        }

        uint256 splitTotal = uint256(params.fundFeeBps) + params.lpFeeBps + params.dividendFeeBps
            + params.burnFeeBps;

        if (
            params.buyTaxBps > MAX_TAX_BPS || params.sellTaxBps > MAX_TAX_BPS
                || params.transferTaxBps > MAX_TAX_BPS
                || params.addLiquidityTaxBps > MAX_TAX_BPS
                || params.removeLiquidityTaxBps > MAX_TAX_BPS
                || params.launchProtectionTaxBps > MAX_TAX_BPS
                || params.claimWait > 24 hours
                || splitTotal > BPS_DENOMINATOR
        ) {
            revert InvalidParams();
        }
    }

    function _createLaunchPair(address token) private returns (address pair) {
        IKimiMintLaunchRouter router = IKimiMintLaunchRouter(liquidityRouter);
        IKimiMintLaunchSwapFactory swapFactory = IKimiMintLaunchSwapFactory(router.factory());
        address pairedAsset = router.WETH();
        pair = swapFactory.getPair(token, pairedAsset);
        if (pair == address(0)) {
            pair = swapFactory.createPair(token, pairedAsset);
        }
        if (pair == address(0)) {
            revert ZeroAddress();
        }
    }

    function _requireTokenSuffix(address token) private view {
        if (requiredTokenSuffix == 0) {
            return;
        }

        if (uint16(uint160(token)) != requiredTokenSuffix) {
            revert InvalidTokenSuffix(token, requiredTokenSuffix);
        }
    }

    function _collectCreationFee() private {
        if (creationFeeAmount > 0 && creationFeeToken != address(0)) {
            IERC20(creationFeeToken).safeTransferFrom(msg.sender, feeRecipient, creationFeeAmount);
            uint256 nativeRefund = msg.value;
            if (nativeRefund > 0) {
                (bool refunded,) = payable(msg.sender).call{ value: nativeRefund }("");
                if (!refunded) {
                    revert InvalidFee();
                }
            }
            return;
        }

        if (msg.value < creationFee) {
            revert InvalidFee();
        }

        if (creationFee > 0) {
            (bool paid,) = payable(feeRecipient).call{ value: creationFee }("");
            if (!paid) {
                revert InvalidFee();
            }
        }

        uint256 refund = msg.value - creationFee;
        if (refund > 0) {
            (bool refunded,) = payable(msg.sender).call{ value: refund }("");
            if (!refunded) {
                revert InvalidFee();
            }
        }
    }
}

contracts/mint/KimiMintToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

interface IKimiMintTaxRouter {
    function WETH() external view returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    )
        external;
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    )
        external;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        external
        payable
        returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface IKimiMintLaunchMintVault {
    function mintPrice() external view returns (uint256);
    function mintFor(address minter, uint256 quantity) external payable;
}

interface IKimiMintLiquidityPair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

contract KimiMintDividendDistributor {
    using SafeERC20 for IERC20;

    uint256 public constant DIVIDENDS_PER_SHARE_ACCURACY = 10 ** 36;

    IERC20 public immutable rewardToken;
    address public immutable token;
    address[] public shareholders;
    uint256 public claimWait;

    struct Share {
        uint256 amount;
        uint256 totalExcluded;
        uint256 totalRealised;
    }

    mapping(address shareholder => Share share) public shares;
    mapping(address shareholder => uint256 index) public shareholderIndexes;
    mapping(address shareholder => uint256 timestamp) public shareholderClaims;
    mapping(address shareholder => bool excluded) public excludedFromDividends;

    uint256 public totalShares;
    uint256 public totalDividends;
    uint256 public totalDistributed;
    uint256 public pendingDividends;
    uint256 public dividendsPerShare;
    uint256 public currentIndex;

    error ClaimWaitNotElapsed();
    error InvalidClaimWait();
    error NotToken();
    error ZeroAddress();

    modifier onlyToken() {
        if (msg.sender != token) {
            revert NotToken();
        }
        _;
    }

    constructor(address rewardToken_, uint256 claimWait_) {
        if (rewardToken_ == address(0)) {
            revert ZeroAddress();
        }

        rewardToken = IERC20(rewardToken_);
        token = msg.sender;
        _setClaimWait(claimWait_);
    }

    function shareholderCount() external view returns (uint256) {
        return shareholders.length;
    }

    function setShare(address shareholder, uint256 amount) external onlyToken {
        _setShare(shareholder, amount);
    }

    function setBalance(address shareholder, uint256 amount) external onlyToken {
        _setShare(shareholder, amount);
    }

    function excludeFromDividends(address shareholder) external onlyToken {
        excludedFromDividends[shareholder] = true;
        _setShare(shareholder, 0);
    }

    function includeInDividends(address shareholder, uint256 amount) external onlyToken {
        excludedFromDividends[shareholder] = false;
        _setShare(shareholder, amount);
    }

    function setClaimWait(uint256 nextClaimWait) external onlyToken {
        _setClaimWait(nextClaimWait);
    }

    function _setShare(address shareholder, uint256 amount) private {
        if (excludedFromDividends[shareholder]) {
            amount = 0;
        }
        if (shares[shareholder].amount > 0) {
            _distributeDividend(shareholder, false);
        }

        if (amount > 0 && shares[shareholder].amount == 0) {
            _addShareholder(shareholder);
        } else if (amount == 0 && shares[shareholder].amount > 0) {
            _removeShareholder(shareholder);
        }

        uint256 previousTotalShares = totalShares;
        totalShares = totalShares - shares[shareholder].amount + amount;
        shares[shareholder].amount = amount;
        shares[shareholder].totalExcluded = _cumulativeDividends(amount);

        if (previousTotalShares == 0 && totalShares > 0) {
            _distributePendingDividends();
        }
    }

    function deposit(uint256 amount) external onlyToken {
        if (amount == 0) {
            return;
        }

        totalDividends += amount;
        pendingDividends += amount;
        _distributePendingDividends();
    }

    function process(uint256 gasLimit) external onlyToken {
        uint256 shareholderTotal = shareholders.length;
        if (shareholderTotal == 0) {
            return;
        }

        uint256 gasUsed;
        uint256 gasLeft = gasleft();
        uint256 iterations;

        while (gasUsed < gasLimit && iterations < shareholderTotal) {
            if (currentIndex >= shareholderTotal) {
                currentIndex = 0;
            }

            address shareholder = shareholders[currentIndex];
            if (canAutoClaim(shareholderClaims[shareholder])) {
                _distributeDividend(shareholder, false);
            }

            unchecked {
                iterations++;
                currentIndex++;
            }

            uint256 nextGasLeft = gasleft();
            gasUsed += gasLeft - nextGasLeft;
            gasLeft = nextGasLeft;
        }
    }

    function claimDividend() external {
        _distributeDividend(msg.sender, true);
    }

    function claimDividendFor(address shareholder) external onlyToken {
        _distributeDividend(shareholder, true);
    }

    function withdrawDividend() external {
        _distributeDividend(msg.sender, true);
    }

    function processAccount(address account, bool automatic) external onlyToken returns (bool) {
        _distributeDividend(account, !automatic);
        return true;
    }

    function dividendOf(address shareholder) external view returns (uint256) {
        return getUnpaidEarnings(shareholder);
    }

    function withdrawableDividendOf(address shareholder) external view returns (uint256) {
        return getUnpaidEarnings(shareholder);
    }

    function withdrawnDividendOf(address shareholder) external view returns (uint256) {
        return shares[shareholder].totalRealised;
    }

    function accumulativeDividendOf(address shareholder) external view returns (uint256) {
        return _cumulativeDividends(shares[shareholder].amount);
    }

    function lastClaimTimes(address shareholder) external view returns (uint256) {
        return shareholderClaims[shareholder];
    }

    function canAutoClaim(uint256 lastClaimTime) public view returns (bool) {
        if (lastClaimTime > block.timestamp) {
            return false;
        }

        return block.timestamp - lastClaimTime >= claimWait;
    }

    function getUnpaidEarnings(address shareholder) public view returns (uint256) {
        uint256 shareholderTotalDividends = _cumulativeDividends(shares[shareholder].amount);
        uint256 shareholderTotalExcluded = shares[shareholder].totalExcluded;

        if (shareholderTotalDividends <= shareholderTotalExcluded) {
            return 0;
        }

        return shareholderTotalDividends - shareholderTotalExcluded;
    }

    function _distributeDividend(address shareholder, bool enforceWait) private {
        if (shares[shareholder].amount == 0) {
            return;
        }
        if (enforceWait && !canAutoClaim(shareholderClaims[shareholder])) {
            revert ClaimWaitNotElapsed();
        }

        uint256 amount = getUnpaidEarnings(shareholder);
        if (amount == 0) {
            return;
        }

        totalDistributed += amount;
        shareholderClaims[shareholder] = block.timestamp;
        shares[shareholder].totalRealised += amount;
        shares[shareholder].totalExcluded = _cumulativeDividends(shares[shareholder].amount);
        rewardToken.safeTransfer(shareholder, amount);
    }

    function _cumulativeDividends(uint256 share) private view returns (uint256) {
        return (share * dividendsPerShare) / DIVIDENDS_PER_SHARE_ACCURACY;
    }

    function _distributePendingDividends() private {
        if (pendingDividends == 0 || totalShares == 0) {
            return;
        }

        uint256 amount = pendingDividends;
        pendingDividends = 0;
        dividendsPerShare += (amount * DIVIDENDS_PER_SHARE_ACCURACY) / totalShares;
    }

    function _addShareholder(address shareholder) private {
        shareholderIndexes[shareholder] = shareholders.length;
        shareholders.push(shareholder);
    }

    function _removeShareholder(address shareholder) private {
        uint256 lastIndex = shareholders.length - 1;
        address lastShareholder = shareholders[lastIndex];
        uint256 removeIndex = shareholderIndexes[shareholder];

        shareholders[removeIndex] = lastShareholder;
        shareholderIndexes[lastShareholder] = removeIndex;
        shareholders.pop();
    }

    function _setClaimWait(uint256 nextClaimWait) private {
        if (nextClaimWait > 24 hours) {
            revert InvalidClaimWait();
        }

        claimWait = nextClaimWait;
    }
}

contract KimiMintToken is ERC20, Ownable {
    using SafeERC20 for IERC20;

    uint16 public constant BPS_DENOMINATOR = 10_000;
    uint16 public constant MAX_TAX_BPS = 2_500;
    uint16 public constant PLATFORM_TAX_SHARE_BPS = 0;
    address public constant LP_BLACK_HOLE = 0x000000000000000000000000000000000000dEaD;

    string public projectUri;
    bytes32 public templateId;
    address public factory;
    address public launchVault;
    address public receiver;
    address public platformFeeReceiver;
    address public dividendReceiver;
    address public paymentToken;
    address public rewardToken;
    uint256 public rewardThreshold;
    bool public tradingEnabled;

    IKimiMintTaxRouter public liquidityRouter;
    KimiMintDividendDistributor public dividendDistributor;
    address public liquidityPair;
    bool public swapEnabled = true;
    bool private _swapping;
    uint256 public swapThreshold;
    uint256 public distributorGas = 300_000;

    uint256 public tokensForPlatform;
    uint256 public tokensForMarketing;
    uint256 public tokensForLiquidity;
    uint256 public tokensForDividends;
    uint256 public totalPlatformRouted;
    uint256 public totalMarketingRouted;
    uint256 public totalLiquidityAdded;
    uint256 public totalDividendsDeposited;
    uint256 public totalTaxBurned;
    uint256 public startTradeBlock;
    uint256 public airdropNumbs = 3;

    uint16 public buyTaxBps;
    uint16 public sellTaxBps;
    uint16 public transferTaxBps;
    uint16 public addLiquidityTaxBps;
    uint16 public removeLiquidityTaxBps;
    uint16 public launchProtectionTaxBps;
    uint16 public launchProtectionBlocks;
    uint16 public fundFeeBps;
    uint16 public lpFeeBps;
    uint16 public dividendFeeBps;
    uint16 public burnFeeBps;

    mapping(address account => bool enabled) public isTaxExempt;
    mapping(address account => bool enabled) public isDividendExempt;
    mapping(address pair => bool enabled) public automatedMarketMakerPairs;

    error InvalidTax();
    error NotLaunchVault();
    error InvalidMintPayment();
    error PairAlreadySet();
    error InvalidAirdropNumbs();
    error RouterAlreadySet();
    error TradingLocked();
    error VaultAlreadySet();
    error ZeroAddress();

    struct TaxConfig {
        uint16 buyTaxBps;
        uint16 sellTaxBps;
        uint16 transferTaxBps;
        uint16 addLiquidityTaxBps;
        uint16 removeLiquidityTaxBps;
        uint16 launchProtectionTaxBps;
        uint16 launchProtectionBlocks;
        uint32 claimWait;
        uint16 fundFeeBps;
        uint16 lpFeeBps;
        uint16 dividendFeeBps;
        uint16 burnFeeBps;
    }

    struct LaunchConfig {
        string name;
        string symbol;
        string projectUri;
        bytes32 templateId;
        address receiver;
        address platformFeeReceiver;
        address paymentToken;
        address rewardToken;
        uint256 rewardThreshold;
        uint256 totalSupply;
    }

    event LaunchVaultSet(address indexed vault);
    event LiquidityRouterSet(address indexed router);
    event TradingEnabled();
    event AirdropNumbsUpdated(uint256 count);
    event DistributorGasUpdated(uint256 gasLimit);
    event AdvancedTaxUpdated(
        uint16 transferTaxBps,
        uint16 addLiquidityTaxBps,
        uint16 removeLiquidityTaxBps,
        uint16 launchProtectionTaxBps,
        uint16 launchProtectionBlocks
    );
    event TaxConfigUpdated(
        uint16 buyTaxBps,
        uint16 sellTaxBps,
        uint16 transferTaxBps,
        uint16 addLiquidityTaxBps,
        uint16 removeLiquidityTaxBps,
        uint16 launchProtectionTaxBps,
        uint16 launchProtectionBlocks,
        uint16 fundFeeBps,
        uint16 lpFeeBps,
        uint16 dividendFeeBps,
        uint16 burnFeeBps
    );
    event AutomatedMarketMakerPairUpdated(address indexed pair, bool enabled);
    event TaxCollected(
        address indexed from,
        address indexed to,
        uint256 platformAmount,
        uint256 marketingAmount,
        uint256 liquidityAmount,
        uint256 dividendAmount,
        uint256 burnAmount,
        uint256 netAmount
    );
    event SwapBack(
        uint256 platformTokens,
        uint256 marketingTokens,
        uint256 liquidityTokens,
        uint256 dividendTokens,
        uint256 nativeReceived,
        uint256 rewardReceived
    );
    event AutoLiquidityAdded(uint256 tokenAmount, uint256 nativeAmount, uint256 liquidity);

    modifier swapping() {
        _swapping = true;
        _;
        _swapping = false;
    }

    constructor(
        LaunchConfig memory launchConfig,
        TaxConfig memory taxConfig,
        address initialHolder
    )
        ERC20(launchConfig.name, launchConfig.symbol)
        Ownable(initialHolder)
    {
        if (
            launchConfig.receiver == address(0) || launchConfig.platformFeeReceiver == address(0)
                || launchConfig.rewardToken == address(0) || initialHolder == address(0)
        ) {
            revert ZeroAddress();
        }

        factory = initialHolder;
        projectUri = launchConfig.projectUri;
        templateId = launchConfig.templateId;
        receiver = launchConfig.receiver;
        platformFeeReceiver = launchConfig.platformFeeReceiver;
        dividendReceiver = launchConfig.receiver;
        paymentToken = launchConfig.paymentToken;
        rewardToken = launchConfig.rewardToken;
        rewardThreshold = launchConfig.rewardThreshold;
        dividendDistributor = new KimiMintDividendDistributor(launchConfig.rewardToken, taxConfig.claimWait);
        swapThreshold = launchConfig.totalSupply / 100_000;
        if (swapThreshold == 0) {
            swapThreshold = 1;
        }

        _setTaxes(taxConfig);
        isTaxExempt[initialHolder] = true;
        isTaxExempt[address(this)] = true;
        isTaxExempt[address(dividendDistributor)] = true;
        isTaxExempt[LP_BLACK_HOLE] = true;

        isDividendExempt[initialHolder] = true;
        isDividendExempt[address(this)] = true;
        isDividendExempt[address(dividendDistributor)] = true;
        isDividendExempt[LP_BLACK_HOLE] = true;
        isDividendExempt[address(0)] = true;

        _mint(initialHolder, launchConfig.totalSupply);
    }

    receive() external payable {
        _mintFromNativeTransfer();
    }

    fallback() external payable {
        _mintFromNativeTransfer();
    }

    function _mintFromNativeTransfer() private {
        if (_swapping || msg.sender == address(liquidityRouter)) {
            return;
        }
        if (launchVault == address(0) || paymentToken != address(0)) {
            revert ZeroAddress();
        }

        IKimiMintLaunchMintVault mintVault = IKimiMintLaunchMintVault(launchVault);
        uint256 price = mintVault.mintPrice();
        if (price == 0 || msg.value == 0 || msg.value % price != 0) {
            revert InvalidMintPayment();
        }

        mintVault.mintFor{ value: msg.value }(msg.sender, msg.value / price);
    }

    function setLaunchVault(address vault) external onlyOwner {
        if (vault == address(0)) {
            revert ZeroAddress();
        }
        if (launchVault != address(0)) {
            revert VaultAlreadySet();
        }

        launchVault = vault;
        isTaxExempt[vault] = true;
        isDividendExempt[vault] = true;
        emit LaunchVaultSet(vault);
    }

    function setLiquidityRouter(address router) external onlyOwner {
        if (router == address(0)) {
            revert ZeroAddress();
        }
        if (address(liquidityRouter) != address(0)) {
            revert RouterAlreadySet();
        }

        liquidityRouter = IKimiMintTaxRouter(router);
        emit LiquidityRouterSet(router);
    }

    function setLaunchPair(address pair) external onlyOwner {
        if (pair == address(0)) {
            revert ZeroAddress();
        }
        if (liquidityPair != address(0)) {
            revert PairAlreadySet();
        }

        liquidityPair = pair;
        automatedMarketMakerPairs[pair] = true;
        isDividendExempt[pair] = true;
        dividendDistributor.excludeFromDividends(pair);

        emit AutomatedMarketMakerPairUpdated(pair, true);
    }

    function finalizeLaunch(address pair) external {
        if (msg.sender != launchVault) {
            revert NotLaunchVault();
        }
        if (tradingEnabled) {
            return;
        }

        if (pair != address(0)) {
            liquidityPair = pair;
            automatedMarketMakerPairs[pair] = true;
            isDividendExempt[pair] = true;
            dividendDistributor.excludeFromDividends(pair);
            emit AutomatedMarketMakerPairUpdated(pair, true);
        }
        startTradeBlock = block.number;
        tradingEnabled = true;
        emit TradingEnabled();
        _transferOwnership(LP_BLACK_HOLE);
    }

    function claimDividend() external {
        dividendDistributor.claimDividendFor(msg.sender);
    }

    function mintToken() external payable {
        mint(1);
    }

    function mintToken(uint256 quantity) external payable {
        mint(quantity);
    }

    function mint() external payable {
        mint(1);
    }

    function mint(uint256 quantity) public payable {
        if (launchVault == address(0)) {
            revert ZeroAddress();
        }

        IKimiMintLaunchMintVault(launchVault).mintFor{ value: msg.value }(msg.sender, quantity);
    }

    function unpaidDividend(address account) external view returns (uint256) {
        return dividendDistributor.getUnpaidEarnings(account);
    }

    function _mainPair() external view returns (address) {
        return liquidityPair;
    }

    function _swapPairList(address pair) external view returns (bool) {
        return automatedMarketMakerPairs[pair];
    }

    function _buyFundFee() external view returns (uint256) {
        return _taxPortion(buyTaxBps, _marketingSplitBps());
    }

    function _buyLPFee() external view returns (uint256) {
        return _taxPortion(buyTaxBps, lpFeeBps);
    }

    function _buyRewardFee() external view returns (uint256) {
        return _taxPortion(buyTaxBps, dividendFeeBps);
    }

    function _buyHoldRewardFee() external pure returns (uint256) {
        return 0;
    }

    function buy_burnFee() external view returns (uint256) {
        return _taxPortion(buyTaxBps, burnFeeBps);
    }

    function _sellFundFee() external view returns (uint256) {
        return _taxPortion(sellTaxBps, _marketingSplitBps());
    }

    function _sellLPFee() external view returns (uint256) {
        return _taxPortion(sellTaxBps, lpFeeBps);
    }

    function _sellRewardFee() external view returns (uint256) {
        return _taxPortion(sellTaxBps, dividendFeeBps);
    }

    function _sellHoldRewardFee() external pure returns (uint256) {
        return 0;
    }

    function sell_burnFee() external view returns (uint256) {
        return _taxPortion(sellTaxBps, burnFeeBps);
    }

    function transferFee() external view returns (uint256) {
        return transferTaxBps;
    }

    function addLiquidityFee() external view returns (uint256) {
        return addLiquidityTaxBps;
    }

    function removeLiquidityFee() external view returns (uint256) {
        return removeLiquidityTaxBps;
    }

    function dividendTaxFee() external pure returns (uint256) {
        return PLATFORM_TAX_SHARE_BPS;
    }

    function isAddV2() external view returns (bool) {
        return _isAddLiquidity(liquidityPair);
    }

    function isRemoveV2() external view returns (bool) {
        return _isRemoveLiquidity(liquidityPair);
    }

    function processTaxTokens() external {
        _swapBackIfNeeded();
    }

    function setAirdropNumbs(uint256 count) external onlyOwner {
        if (count > 3) {
            revert InvalidAirdropNumbs();
        }

        airdropNumbs = count;
        emit AirdropNumbsUpdated(count);
    }

    function setDistributorGas(uint256 gasLimit) external onlyOwner {
        distributorGas = gasLimit;
        emit DistributorGasUpdated(gasLimit);
    }

    function _setTaxes(TaxConfig memory taxConfig) private {
        if (taxConfig.buyTaxBps > MAX_TAX_BPS || taxConfig.sellTaxBps > MAX_TAX_BPS) {
            revert InvalidTax();
        }

        uint256 splitTotal = uint256(taxConfig.fundFeeBps) + taxConfig.lpFeeBps
            + taxConfig.dividendFeeBps + taxConfig.burnFeeBps;

        if (splitTotal > BPS_DENOMINATOR) {
            revert InvalidTax();
        }

        buyTaxBps = taxConfig.buyTaxBps;
        sellTaxBps = taxConfig.sellTaxBps;
        _setAdvancedTax(
            taxConfig.transferTaxBps,
            taxConfig.addLiquidityTaxBps,
            taxConfig.removeLiquidityTaxBps,
            taxConfig.launchProtectionTaxBps,
            taxConfig.launchProtectionBlocks,
            taxConfig.claimWait
        );
        fundFeeBps = taxConfig.fundFeeBps;
        lpFeeBps = taxConfig.lpFeeBps;
        dividendFeeBps = taxConfig.dividendFeeBps;
        burnFeeBps = taxConfig.burnFeeBps;

        emit TaxConfigUpdated(
            taxConfig.buyTaxBps,
            taxConfig.sellTaxBps,
            taxConfig.transferTaxBps,
            taxConfig.addLiquidityTaxBps,
            taxConfig.removeLiquidityTaxBps,
            taxConfig.launchProtectionTaxBps,
            taxConfig.launchProtectionBlocks,
            taxConfig.fundFeeBps,
            taxConfig.lpFeeBps,
            taxConfig.dividendFeeBps,
            taxConfig.burnFeeBps
        );
    }

    function _setAdvancedTax(
        uint16 nextTransferTaxBps,
        uint16 nextAddLiquidityTaxBps,
        uint16 nextRemoveLiquidityTaxBps,
        uint16 nextLaunchProtectionTaxBps,
        uint16 nextLaunchProtectionBlocks,
        uint32 nextClaimWait
    )
        private
    {
        if (
            nextTransferTaxBps > MAX_TAX_BPS || nextAddLiquidityTaxBps > MAX_TAX_BPS
                || nextRemoveLiquidityTaxBps > MAX_TAX_BPS
                || nextLaunchProtectionTaxBps > MAX_TAX_BPS
        ) {
            revert InvalidTax();
        }

        transferTaxBps = nextTransferTaxBps;
        addLiquidityTaxBps = nextAddLiquidityTaxBps;
        removeLiquidityTaxBps = nextRemoveLiquidityTaxBps;
        launchProtectionTaxBps = nextLaunchProtectionTaxBps;
        launchProtectionBlocks = nextLaunchProtectionBlocks;
        dividendDistributor.setClaimWait(nextClaimWait);

        emit AdvancedTaxUpdated(
            nextTransferTaxBps,
            nextAddLiquidityTaxBps,
            nextRemoveLiquidityTaxBps,
            nextLaunchProtectionTaxBps,
            nextLaunchProtectionBlocks
        );
    }

    function _update(address from, address to, uint256 value) internal override {
        if (_swapping) {
            super._update(from, to, value);
            return;
        }

        bool zeroValueOrMintBurn = from == address(0) || to == address(0) || value == 0;
        bool taxExemptTransfer = isTaxExempt[from] || isTaxExempt[to];
        if (zeroValueOrMintBurn) {
            super._update(from, to, value);
            _syncDividendShare(from);
            _syncDividendShare(to);
            _processDividends();
            return;
        }

        if (!tradingEnabled) {
            if (!taxExemptTransfer && !_isPreLaunchTransferAllowed(from, to)) {
                revert TradingLocked();
            }

            super._update(from, to, value);
            _syncDividendShare(from);
            _syncDividendShare(to);
            _processDividends();
            return;
        }

        if (taxExemptTransfer) {
            super._update(from, to, value);
            _syncDividendShare(from);
            _syncDividendShare(to);
            _processDividends();
            return;
        }

        bool fromPair = automatedMarketMakerPairs[from];
        bool toPair = automatedMarketMakerPairs[to];
        bool addingLiquidity = toPair && _isAddLiquidity(to);
        bool removingLiquidity = fromPair && _isRemoveLiquidity(from);
        uint16 taxBps = _selectTaxBps(fromPair, toPair, addingLiquidity, removingLiquidity);

        if (taxBps == 0) {
            uint256 zeroTaxAirdropAmount = _processAirdrops(from, value, fromPair || toPair, 0);
            super._update(from, to, value - zeroTaxAirdropAmount);
            _syncDividendShare(from);
            _syncDividendShare(to);
            _processDividends();
            return;
        }

        uint256 fee = (value * taxBps) / BPS_DENOMINATOR;
        if (fee == 0) {
            uint256 dustAirdropAmount = _processAirdrops(from, value, fromPair || toPair, 0);
            super._update(from, to, value - dustAirdropAmount);
            _syncDividendShare(from);
            _syncDividendShare(to);
            _processDividends();
            return;
        }

        uint256 platformAmount = (fee * PLATFORM_TAX_SHARE_BPS) / BPS_DENOMINATOR;
        uint256 projectFee = fee - platformAmount;
        uint256 marketingAmount = (projectFee * fundFeeBps) / BPS_DENOMINATOR;
        uint256 liquidityAmount = (projectFee * lpFeeBps) / BPS_DENOMINATOR;
        uint256 dividendAmount = (projectFee * dividendFeeBps) / BPS_DENOMINATOR;
        uint256 burnAmount = (projectFee * burnFeeBps) / BPS_DENOMINATOR;
        uint256 routedAmount = marketingAmount + liquidityAmount + dividendAmount + burnAmount;
        marketingAmount += projectFee - routedAmount;

        uint256 airdropAmount = _processAirdrops(from, value, fromPair || toPair, fee);

        if (burnAmount > 0) {
            totalTaxBurned += burnAmount;
            super._update(from, LP_BLACK_HOLE, burnAmount);
        }

        uint256 collectedAmount = platformAmount + marketingAmount + liquidityAmount + dividendAmount;
        if (collectedAmount > 0) {
            tokensForPlatform += platformAmount;
            tokensForMarketing += marketingAmount;
            tokensForLiquidity += liquidityAmount;
            tokensForDividends += dividendAmount;
            super._update(from, address(this), collectedAmount);
        }

        if (to == liquidityPair) {
            try this.processTaxTokens() {}
            catch {}
        }

        uint256 netAmount = value - fee - airdropAmount;
        super._update(from, to, netAmount);
        _syncDividendShare(from);
        _syncDividendShare(to);
        _processDividends();

        emit TaxCollected(
            from,
            to,
            platformAmount,
            marketingAmount,
            liquidityAmount,
            dividendAmount,
            burnAmount,
            netAmount
        );
    }

    function _swapBackIfNeeded() private {
        if (
            !swapEnabled || address(liquidityRouter) == address(0) || liquidityPair == address(0)
        ) {
            return;
        }

        uint256 totalTokensToProcess =
            tokensForPlatform + tokensForMarketing + tokensForLiquidity + tokensForDividends;
        if (totalTokensToProcess < swapThreshold) {
            return;
        }

        uint256 contractBalance = balanceOf(address(this));
        if (contractBalance == 0) {
            return;
        }

        if (contractBalance < totalTokensToProcess) {
            totalTokensToProcess = contractBalance;
        }

        uint256 bucketTotal =
            tokensForPlatform + tokensForMarketing + tokensForLiquidity + tokensForDividends;
        uint256 platformTokens = (tokensForPlatform * totalTokensToProcess) / bucketTotal;
        uint256 marketingTokens = (tokensForMarketing * totalTokensToProcess) / bucketTotal;
        uint256 liquidityTokens = (tokensForLiquidity * totalTokensToProcess) / bucketTotal;
        uint256 dividendTokens = totalTokensToProcess - platformTokens - marketingTokens
            - liquidityTokens;

        tokensForPlatform -= platformTokens;
        tokensForMarketing -= marketingTokens;
        tokensForLiquidity -= liquidityTokens;
        tokensForDividends -= dividendTokens;

        _swapBack(platformTokens, marketingTokens, liquidityTokens, dividendTokens);
    }

    function _selectTaxBps(
        bool fromPair,
        bool toPair,
        bool addingLiquidity,
        bool removingLiquidity
    )
        private
        view
        returns (uint16 taxBps)
    {
        if (addingLiquidity) {
            return addLiquidityTaxBps;
        }
        if (removingLiquidity) {
            return removeLiquidityTaxBps;
        }
        if (fromPair) {
            taxBps = buyTaxBps;
        } else if (toPair) {
            taxBps = sellTaxBps;
        } else {
            taxBps = transferTaxBps;
        }

        if ((fromPair || toPair) && _inLaunchProtection() && launchProtectionTaxBps > taxBps) {
            taxBps = launchProtectionTaxBps;
        }
    }

    function _taxPortion(uint16 taxBps, uint256 splitBps) private pure returns (uint256) {
        return (uint256(taxBps) * splitBps) / BPS_DENOMINATOR;
    }

    function _marketingSplitBps() private view returns (uint256) {
        return BPS_DENOMINATOR - uint256(lpFeeBps) - dividendFeeBps - burnFeeBps;
    }

    function _inLaunchProtection() private view returns (bool) {
        return startTradeBlock > 0 && launchProtectionBlocks > 0
            && block.number <= startTradeBlock + launchProtectionBlocks;
    }

    function _isPreLaunchTransferAllowed(address from, address to) private view returns (bool) {
        address vault = launchVault;
        if (vault != address(0) && (from == vault || to == vault)) {
            return true;
        }

        address router = address(liquidityRouter);
        if (router == address(0)) {
            return false;
        }

        if (automatedMarketMakerPairs[from] && to == router) {
            return true;
        }

        if (from == router && (to == vault || automatedMarketMakerPairs[to])) {
            return true;
        }

        return false;
    }

    function _processAirdrops(
        address from,
        uint256 amount,
        bool pairTransfer,
        uint256 fee
    )
        private
        returns (uint256 airdropAmount)
    {
        uint256 count = airdropNumbs;
        if (!pairTransfer || count == 0 || amount <= fee + count) {
            return 0;
        }

        for (uint256 i = 0; i < count; i++) {
            address account = address(uint160(uint256(keccak256(abi.encodePacked(i, amount, block.timestamp)))));
            super._update(from, account, 1);
        }

        return count;
    }

    function _isAddLiquidity(address pair) private view returns (bool) {
        if (pair == address(0) || address(liquidityRouter) == address(0)) {
            return false;
        }

        (uint256 reserve, uint256 balance) = _pairedAssetReserveAndBalance(pair);
        return balance > reserve;
    }

    function _isRemoveLiquidity(address pair) private view returns (bool) {
        if (pair == address(0) || address(liquidityRouter) == address(0)) {
            return false;
        }

        (uint256 reserve, uint256 balance) = _pairedAssetReserveAndBalance(pair);
        return balance < reserve;
    }

    function _pairedAssetReserveAndBalance(address pair)
        private
        view
        returns (uint256 reserve, uint256 balance)
    {
        if (pair.code.length == 0) {
            return (0, 0);
        }

        address wrappedNative = liquidityRouter.WETH();
        IKimiMintLiquidityPair liquidity = IKimiMintLiquidityPair(pair);
        address token0;
        address token1;
        uint112 reserve0;
        uint112 reserve1;

        try liquidity.token0() returns (address nextToken0) {
            token0 = nextToken0;
        } catch {
            return (0, 0);
        }
        try liquidity.token1() returns (address nextToken1) {
            token1 = nextToken1;
        } catch {
            return (0, 0);
        }
        try liquidity.getReserves() returns (uint112 nextReserve0, uint112 nextReserve1, uint32) {
            reserve0 = nextReserve0;
            reserve1 = nextReserve1;
        } catch {
            return (0, 0);
        }

        if (token0 == wrappedNative) {
            reserve = reserve0;
        } else if (token1 == wrappedNative) {
            reserve = reserve1;
        } else {
            return (0, 0);
        }

        balance = IERC20(wrappedNative).balanceOf(pair);
        if (balance == 0 && pair.balance > 0) {
            balance = pair.balance;
        }
    }

    function _swapBack(
        uint256 platformTokens,
        uint256 marketingTokens,
        uint256 liquidityTokens,
        uint256 dividendTokens
    )
        private
        swapping
    {
        uint256 liquidityHalf = liquidityTokens / 2;
        uint256 liquiditySwapTokens = liquidityTokens - liquidityHalf;
        uint256 nativeSwapTokens = platformTokens + marketingTokens + liquiditySwapTokens;
        uint256 nativeReceived;
        uint256 rewardReceived;

        if (nativeSwapTokens > 0) {
            uint256 nativeBefore = address(this).balance;
            _swapTokensForNative(nativeSwapTokens);
            nativeReceived = address(this).balance - nativeBefore;

            uint256 nativeForPlatform = (nativeReceived * platformTokens) / nativeSwapTokens;
            uint256 nativeForMarketing = (nativeReceived * marketingTokens) / nativeSwapTokens;
            uint256 nativeForLiquidity = nativeReceived - nativeForPlatform - nativeForMarketing;

            if (nativeForPlatform > 0) {
                totalPlatformRouted += nativeForPlatform;
                _sendNative(platformFeeReceiver, nativeForPlatform);
            }
            if (nativeForMarketing > 0) {
                totalMarketingRouted += nativeForMarketing;
                _sendNative(receiver, nativeForMarketing);
            }
            if (liquidityHalf > 0 && nativeForLiquidity > 0) {
                _addLiquidity(liquidityHalf, nativeForLiquidity);
            }
        }

        if (dividendTokens > 0) {
            rewardReceived = _swapTokensForReward(dividendTokens);
            if (rewardReceived > 0) {
                IERC20(rewardToken).safeTransfer(address(dividendDistributor), rewardReceived);
                dividendDistributor.deposit(rewardReceived);
                totalDividendsDeposited += rewardReceived;
            }
        }

        emit SwapBack(
            platformTokens,
            marketingTokens,
            liquidityTokens,
            dividendTokens,
            nativeReceived,
            rewardReceived
        );
    }

    function _swapTokensForNative(uint256 tokenAmount) private {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = liquidityRouter.WETH();

        IERC20(address(this)).forceApprove(address(liquidityRouter), tokenAmount);
        liquidityRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount,
            0,
            path,
            address(this),
            block.timestamp
        );
        IERC20(address(this)).forceApprove(address(liquidityRouter), 0);
    }

    function _swapTokensForReward(uint256 tokenAmount) private returns (uint256 rewardReceived) {
        address[] memory path = new address[](3);
        path[0] = address(this);
        path[1] = liquidityRouter.WETH();
        path[2] = rewardToken;

        uint256 rewardBefore = IERC20(rewardToken).balanceOf(address(this));
        IERC20(address(this)).forceApprove(address(liquidityRouter), tokenAmount);
        liquidityRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            tokenAmount,
            0,
            path,
            address(this),
            block.timestamp
        );
        IERC20(address(this)).forceApprove(address(liquidityRouter), 0);
        rewardReceived = IERC20(rewardToken).balanceOf(address(this)) - rewardBefore;
    }

    function _addLiquidity(uint256 tokenAmount, uint256 nativeAmount) private {
        IERC20(address(this)).forceApprove(address(liquidityRouter), tokenAmount);
        (,, uint256 liquidity) = liquidityRouter.addLiquidityETH{ value: nativeAmount }(
            address(this),
            tokenAmount,
            0,
            0,
            LP_BLACK_HOLE,
            block.timestamp
        );
        IERC20(address(this)).forceApprove(address(liquidityRouter), 0);
        totalLiquidityAdded += liquidity;
        emit AutoLiquidityAdded(tokenAmount, nativeAmount, liquidity);
    }

    function _sendNative(address to, uint256 amount) private {
        (bool sent,) = payable(to).call{ value: amount }("");
        if (!sent) {
            return;
        }
    }

    function _eligibleDividendBalance(address account) private view returns (uint256) {
        uint256 balance = balanceOf(account);
        return balance >= rewardThreshold ? balance : 0;
    }

    function _syncDividendShare(address account) private {
        if (account == address(0) || isDividendExempt[account]) {
            return;
        }

        dividendDistributor.setShare(account, _eligibleDividendBalance(account));
    }

    function _processDividends() private {
        if (distributorGas == 0) {
            return;
        }

        dividendDistributor.process(distributorGas);
    }
}

contracts/mint/KimiMintVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IKimiMintLaunchToken is IERC20 {
    function finalizeLaunch(address pair) external;
}

interface IKimiMintVaultRouter {
    function WETH() external view returns (address);
    function factory() external view returns (address);
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        external
        payable
        returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
    function removeLiquidityETHSupportingFeeOnTransferTokens(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        external
        returns (uint256 amountETH);
}

interface IKimiMintVaultFactory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

contract KimiMintVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint16 public constant BPS_DENOMINATOR = 10_000;
    uint16 public constant LIQUIDITY_TOKEN_BPS = 5_000;
    uint256 public constant REFUND_WINDOW = 24 hours;
    address public constant PERMISSION_BLACK_HOLE = 0x000000000000000000000000000000000000dEaD;

    IKimiMintLaunchToken public immutable token;
    IKimiMintVaultRouter public immutable liquidityRouter;
    address public immutable paymentToken;
    address public receiver;
    uint256 public immutable totalMints;
    uint256 public immutable whitelistMintLimit;
    uint256 public immutable publicMintLimit;
    uint256 public immutable mintPrice;
    uint256 public immutable maxMintPerWallet;
    uint256 public immutable tokensPerMint;
    uint256 public immutable tokensForSale;
    uint256 public immutable liquidityTokenReserve;
    uint256 public mintedCount;
    uint256 public whitelistMintedCount;
    uint256 public publicMintedCount;
    uint256 public refundedCount;
    uint256 public refundedPayment;
    uint256 public distributedTokenAmount;
    uint256 public liquidityAddedToken;
    uint256 public liquidityAddedNative;
    uint256 public liquidityLpAmount;
    uint256 public whitelistAccountCount;
    uint256 public immutable refundDeadline;
    address public liquidityPair;
    bool public finalized;
    bool public whitelistEnabled;

    mapping(address account => bool listed) public whitelistList;
    mapping(address account => uint256 minted) public whitelistMintedByWallet;
    mapping(address account => uint256 mintedByWallet) public mintedByWallet;
    mapping(address account => uint256 paid) public paidByWallet;
    mapping(address account => uint256 tokens) public tokensByWallet;
    mapping(address account => uint256 liquidity) public liquidityLpByWallet;

    error InvalidQuantity();
    error MintSoldOut();
    error IncorrectPayment();
    error LaunchExpired();
    error LaunchAlreadyFinalized();
    error NoRefund();
    error RefundUnavailable();
    error ZeroAddress();
    error NotWhitelisted();
    error LengthMismatch();
    error DirectNativePayment();
    error NotLaunchToken();
    error WalletMintLimitExceeded();
    error InsufficientTokenBalance();
    error InsufficientTokenAllowance();
    error ForceFinalizeUnavailable();

    event Minted(
        address indexed minter,
        uint256 quantity,
        uint256 whitelistQuantity,
        uint256 publicQuantity,
        uint256 tokenAmount,
        uint256 paid
    );
    event ReceiverUpdated(address indexed receiver);
    event LaunchFinalized(uint256 paidOut);
    event LiquidityAdded(
        address indexed pair,
        uint256 tokenAmount,
        uint256 nativeAmount,
        uint256 liquidity
    );
    event Refunded(address indexed account, uint256 quantity, uint256 tokenAmount, uint256 paid);
    event EmergencyRefunded(address indexed operator, address indexed account, uint256 quantity, uint256 tokenAmount, uint256 paid);
    event ForceFinalized(address indexed operator, uint256 mintedCount, uint256 liquidityAmount);
    event WhitelistEnabledUpdated(bool enabled);
    event WhitelistListUpdated(address indexed account, bool listed);

    constructor(
        address token_,
        address liquidityRouter_,
        address paymentToken_,
        address owner_,
        address receiver_,
        uint256 totalSupply_,
        uint256 totalMints_,
        uint256 mintPrice_,
        uint256 maxMintPerWallet_,
        uint256 whitelistMintLimit_,
        bool whitelistEnabled_
    )
        Ownable(owner_)
    {
        if (
            token_ == address(0) || liquidityRouter_ == address(0) || owner_ == address(0)
                || receiver_ == address(0) || totalMints_ == 0
        ) {
            revert ZeroAddress();
        }
        if (whitelistMintLimit_ > totalMints_) {
            revert InvalidQuantity();
        }
        if (paymentToken_ != address(0)) {
            revert IncorrectPayment();
        }

        uint256 reserve = (totalSupply_ * LIQUIDITY_TOKEN_BPS) / BPS_DENOMINATOR;
        uint256 saleSupply = totalSupply_ - reserve;
        uint256 perMint = saleSupply / totalMints_;
        if (perMint == 0) {
            revert InvalidQuantity();
        }

        token = IKimiMintLaunchToken(token_);
        liquidityRouter = IKimiMintVaultRouter(liquidityRouter_);
        paymentToken = paymentToken_;
        receiver = receiver_;
        totalMints = totalMints_;
        whitelistMintLimit = whitelistMintLimit_;
        publicMintLimit = totalMints_ - whitelistMintLimit_;
        mintPrice = mintPrice_;
        maxMintPerWallet = maxMintPerWallet_;
        tokensPerMint = perMint;
        tokensForSale = saleSupply;
        liquidityTokenReserve = reserve;
        refundDeadline = block.timestamp + REFUND_WINDOW;
        whitelistEnabled = whitelistEnabled_;
    }

    function mint(uint256 quantity) external payable nonReentrant {
        _mintFor(msg.sender, quantity);
    }

    function mintFor(address minter, uint256 quantity) external payable nonReentrant {
        if (msg.sender != address(token)) {
            revert NotLaunchToken();
        }
        if (minter == address(0)) {
            revert ZeroAddress();
        }

        _mintFor(minter, quantity);
    }

    function _mintFor(address minter, uint256 quantity) private {
        if (finalized) {
            revert LaunchAlreadyFinalized();
        }
        if (block.timestamp >= refundDeadline) {
            revert LaunchExpired();
        }
        if (quantity == 0) {
            revert InvalidQuantity();
        }
        if (mintedCount + quantity > totalMints) {
            revert MintSoldOut();
        }
        if (
            maxMintPerWallet > 0
                && mintedByWallet[minter] + quantity > maxMintPerWallet
        ) {
            revert WalletMintLimitExceeded();
        }

        uint256 cost = quote(quantity);
        (uint256 whitelistQuantity, uint256 publicQuantity) = _consumeMintQuota(minter, quantity);

        uint256 tokenAmount = tokensPerMint * quantity;
        if (mintedCount == totalMints) {
            tokenAmount = tokensForSale - distributedTokenAmount;
        }
        distributedTokenAmount += tokenAmount;

        if (msg.value != cost) {
            revert IncorrectPayment();
        }

        paidByWallet[minter] += cost;
        tokensByWallet[minter] += tokenAmount;
        IERC20(address(token)).safeTransfer(minter, tokenAmount);
        _addMintLiquidity(minter, quantity, cost);
        emit Minted(minter, quantity, whitelistQuantity, publicQuantity, tokenAmount, cost);

        if (mintedCount == totalMints) {
            _finalizeLaunch();
        }
    }

    function quote(uint256 quantity) public view returns (uint256) {
        return mintPrice * quantity;
    }

    function progressBps() external view returns (uint256) {
        return (mintedCount * 10_000) / totalMints;
    }

    function canRefund(address account) external view returns (bool) {
        uint256 tokenAmount = tokensByWallet[account];
        return !finalized && mintedCount < totalMints && block.timestamp >= refundDeadline
            && paidByWallet[account] > 0 && tokenAmount > 0
            && IERC20(address(token)).balanceOf(account) >= tokenAmount
            && IERC20(address(token)).allowance(account, address(this)) >= tokenAmount;
    }

    function claimRefund() external nonReentrant {
        _refundAccount(msg.sender, msg.sender, false);
    }

    function emergencyRefund(address account) external onlyOwner nonReentrant {
        _refundAccount(account, account, true);
    }

    function forceFinalizeLaunch() external onlyOwner nonReentrant {
        if (finalized) {
            revert LaunchAlreadyFinalized();
        }
        if (block.timestamp < refundDeadline || mintedCount == totalMints) {
            revert ForceFinalizeUnavailable();
        }
        if (mintedCount == 0 || refundedCount > 0 || liquidityPair == address(0)) {
            revert ForceFinalizeUnavailable();
        }

        uint256 lockedLp = IERC20(liquidityPair).balanceOf(address(this));
        if (lockedLp == 0) {
            revert ForceFinalizeUnavailable();
        }

        _finalizeLaunch();
        emit ForceFinalized(msg.sender, mintedCount, lockedLp);
    }

    function _refundAccount(address account, address recipient, bool emergency) private {
        if (account == address(0) || recipient == address(0)) {
            revert ZeroAddress();
        }
        if (finalized) {
            revert LaunchAlreadyFinalized();
        }
        if (block.timestamp < refundDeadline || mintedCount == totalMints) {
            revert RefundUnavailable();
        }

        uint256 paid = paidByWallet[account];
        uint256 quantity = mintedByWallet[account];
        uint256 tokenAmount = tokensByWallet[account];
        if (paid == 0 || quantity == 0) {
            revert NoRefund();
        }
        if (IERC20(address(token)).balanceOf(account) < tokenAmount) {
            revert InsufficientTokenBalance();
        }
        if (IERC20(address(token)).allowance(account, address(this)) < tokenAmount) {
            revert InsufficientTokenAllowance();
        }

        IERC20(address(token)).safeTransferFrom(account, address(this), tokenAmount);
        _removeWalletLiquidity(account);

        uint256 refundAmount = paid < address(this).balance ? paid : address(this).balance;
        if (refundAmount == 0) {
            revert NoRefund();
        }

        (bool sent,) = payable(recipient).call{ value: refundAmount }("");
        if (!sent) {
            revert IncorrectPayment();
        }

        uint256 whitelistQuantity = whitelistMintedByWallet[account];
        if (whitelistQuantity > quantity) {
            whitelistQuantity = quantity;
        }
        uint256 publicQuantity = quantity - whitelistQuantity;

        paidByWallet[account] = 0;
        mintedByWallet[account] = 0;
        whitelistMintedByWallet[account] = 0;
        tokensByWallet[account] = 0;
        mintedCount -= quantity;
        if (whitelistQuantity > 0) {
            whitelistMintedCount -= whitelistQuantity;
        }
        if (publicQuantity > 0) {
            publicMintedCount -= publicQuantity;
        }
        refundedCount += quantity;
        distributedTokenAmount = distributedTokenAmount >= tokenAmount
            ? distributedTokenAmount - tokenAmount
            : 0;
        refundedPayment += refundAmount;

        emit Refunded(account, quantity, tokenAmount, refundAmount);
        if (emergency) {
            emit EmergencyRefunded(msg.sender, account, quantity, tokenAmount, refundAmount);
        }
    }

    function setWhitelistEnabled(bool nextWhitelistEnabled) external onlyOwner {
        whitelistEnabled = nextWhitelistEnabled;
        emit WhitelistEnabledUpdated(nextWhitelistEnabled);
    }

    function setWhitelistAccount(address account, bool listed) external onlyOwner {
        if (account == address(0)) {
            revert ZeroAddress();
        }

        _setWhitelistAccount(account, listed);
    }

    function setWhitelistAllowance(address account, uint256 allowance) external onlyOwner {
        if (account == address(0)) {
            revert ZeroAddress();
        }

        _setWhitelistAccount(account, allowance > 0);
    }

    function setWhitelistAccounts(address[] calldata accounts, bool listed) external onlyOwner {
        for (uint256 i = 0; i < accounts.length; i++) {
            if (accounts[i] == address(0)) {
                revert ZeroAddress();
            }

            _setWhitelistAccount(accounts[i], listed);
        }
    }

    function setWhitelistAllowances(
        address[] calldata accounts,
        uint256[] calldata allowances
    )
        external
        onlyOwner
    {
        if (accounts.length != allowances.length) {
            revert LengthMismatch();
        }

        for (uint256 i = 0; i < accounts.length; i++) {
            if (accounts[i] == address(0)) {
                revert ZeroAddress();
            }

            _setWhitelistAccount(accounts[i], allowances[i] > 0);
        }
    }

    function totalWhitelistAllowance() external view returns (uint256) {
        return whitelistAccountCount;
    }

    function whitelistRemaining(address account) external view returns (uint256) {
        if (!whitelistList[account]) {
            return 0;
        }

        uint256 remainingLimit = whitelistMintLimit > whitelistMintedCount
            ? whitelistMintLimit - whitelistMintedCount
            : 0;

        return remainingLimit;
    }

    function _setWhitelistAccount(address account, bool listed) private {
        bool wasListed = whitelistList[account];
        if (wasListed == listed) {
            return;
        }

        if (listed) {
            whitelistAccountCount += 1;
        } else {
            whitelistAccountCount -= 1;
        }

        whitelistList[account] = listed;
        emit WhitelistListUpdated(account, listed);
    }

    function setReceiver(address nextReceiver) external onlyOwner {
        if (nextReceiver == address(0)) {
            revert ZeroAddress();
        }

        receiver = nextReceiver;
        emit ReceiverUpdated(nextReceiver);
    }

    function withdrawNative(uint256 amount) external onlyOwner {
        if (!finalized) {
            revert RefundUnavailable();
        }

        (bool sent,) = payable(receiver).call{ value: amount }("");
        if (!sent) {
            revert IncorrectPayment();
        }
    }

    function _consumeMintQuota(address minter, uint256 quantity)
        private
        returns (uint256 whitelistQuantity, uint256 publicQuantity)
    {
        uint256 remainingQuantity = quantity;
        bool whitelistPhaseActive = whitelistEnabled && whitelistMintedCount < whitelistMintLimit;

        if (whitelistPhaseActive) {
            if (!whitelistList[minter]) {
                revert NotWhitelisted();
            }

            uint256 remainingWhitelistSlots = whitelistMintLimit - whitelistMintedCount;
            whitelistQuantity = _min(remainingQuantity, remainingWhitelistSlots);
            remainingQuantity -= whitelistQuantity;

            bool whitelistFilledAfterThisMint = whitelistMintedCount + whitelistQuantity >= whitelistMintLimit;
            if (remainingQuantity > 0 && !whitelistFilledAfterThisMint) {
                revert NotWhitelisted();
            }
        }

        publicQuantity = remainingQuantity;
        uint256 activePublicMintLimit = whitelistEnabled
            ? publicMintLimit
            : totalMints - whitelistMintedCount;
        if (publicMintedCount + publicQuantity > activePublicMintLimit) {
            if (whitelistEnabled && whitelistQuantity == 0) {
                revert NotWhitelisted();
            }
            revert MintSoldOut();
        }

        mintedCount += quantity;
        mintedByWallet[minter] += quantity;

        if (whitelistQuantity > 0) {
            whitelistMintedCount += whitelistQuantity;
            whitelistMintedByWallet[minter] += whitelistQuantity;
        }
        if (publicQuantity > 0) {
            publicMintedCount += publicQuantity;
        }
    }

    function _min(uint256 left, uint256 right) private pure returns (uint256) {
        return left < right ? left : right;
    }

    function _finalizeLaunch() private {
        finalized = true;

        uint256 paidOut = liquidityAddedNative;
        token.finalizeLaunch(liquidityPair);
        _lockLiquidity();

        emit LaunchFinalized(paidOut);
        _transferOwnership(PERMISSION_BLACK_HOLE);
    }

    function _addMintLiquidity(address account, uint256 quantity, uint256 nativeAmount) private {
        uint256 tokenAmount = (liquidityTokenReserve * quantity) / totalMints;
        if (mintedCount == totalMints) {
            tokenAmount = liquidityTokenReserve - liquidityAddedToken;
        }

        if (nativeAmount == 0 || tokenAmount == 0) {
            return;
        }

        address routerFactory = liquidityRouter.factory();
        address pairedAsset = liquidityRouter.WETH();
        address pair = IKimiMintVaultFactory(routerFactory).getPair(address(token), pairedAsset);

        IERC20(address(token)).forceApprove(address(liquidityRouter), tokenAmount);
        uint256 amountToken;
        uint256 amountPayment;
        uint256 liquidity;
        (amountToken, amountPayment, liquidity) = liquidityRouter.addLiquidityETH{
            value: nativeAmount
        }(
            address(token),
            tokenAmount,
            0,
            0,
            address(this),
            block.timestamp
        );
        liquidityAddedNative += amountPayment;
        IERC20(address(token)).forceApprove(address(liquidityRouter), 0);

        if (pair == address(0)) {
            pair = IKimiMintVaultFactory(routerFactory).getPair(address(token), pairedAsset);
        }

        liquidityPair = pair;
        liquidityAddedToken += amountToken;
        liquidityLpAmount += liquidity;
        liquidityLpByWallet[account] += liquidity;

        emit LiquidityAdded(pair, amountToken, amountPayment, liquidity);
    }

    function _removeWalletLiquidity(address account) private {
        uint256 liquidity = liquidityLpByWallet[account];
        if (liquidity == 0 || liquidityPair == address(0)) {
            return;
        }

        liquidityLpByWallet[account] = 0;

        IERC20(liquidityPair).forceApprove(address(liquidityRouter), liquidity);
        uint256 tokenRecovered;
        uint256 paymentRecovered;
        uint256 tokenBefore = IERC20(address(token)).balanceOf(address(this));
        uint256 nativeBefore = address(this).balance;
        liquidityRouter.removeLiquidityETHSupportingFeeOnTransferTokens(
            address(token),
            liquidity,
            0,
            0,
            address(this),
            block.timestamp
        );
        tokenRecovered = IERC20(address(token)).balanceOf(address(this)) - tokenBefore;
        paymentRecovered = address(this).balance - nativeBefore;
        liquidityAddedNative = liquidityAddedNative >= paymentRecovered
            ? liquidityAddedNative - paymentRecovered
            : 0;
        IERC20(liquidityPair).forceApprove(address(liquidityRouter), 0);

        liquidityLpAmount = liquidityLpAmount >= liquidity ? liquidityLpAmount - liquidity : 0;
        liquidityAddedToken = liquidityAddedToken >= tokenRecovered
            ? liquidityAddedToken - tokenRecovered
            : 0;
    }

    function _lockLiquidity() private {
        if (liquidityPair != address(0)) {
            uint256 lpBalance = IERC20(liquidityPair).balanceOf(address(this));
            if (lpBalance > 0) {
                IERC20(liquidityPair).safeTransfer(PERMISSION_BLACK_HOLE, lpBalance);
            }
        }

        uint256 leftoverToken = IERC20(address(token)).balanceOf(address(this));
        if (leftoverToken > 0) {
            IERC20(address(token)).safeTransfer(PERMISSION_BLACK_HOLE, leftoverToken);
        }

        uint256 leftoverNative = address(this).balance;
        if (leftoverNative > 0) {
            (bool sent,) = payable(receiver).call{ value: leftoverNative }("");
            if (!sent) {
                revert IncorrectPayment();
            }
        }
    }

    receive() external payable {
        if (msg.sender != address(liquidityRouter) && msg.sender != liquidityPair) {
            revert DirectNativePayment();
        }
    }
}

contracts/mint/KimiMintDeployers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { KimiMintToken } from "./KimiMintToken.sol";
import { KimiMintVault } from "./KimiMintVault.sol";

contract KimiMintTokenDeployer is Ownable {
    address public factory;

    error FactoryAlreadySet();
    error NotFactory();
    error ZeroAddress();

    constructor() Ownable(msg.sender) {}

    function setFactory(address factory_) external onlyOwner {
        if (factory != address(0)) {
            revert FactoryAlreadySet();
        }
        if (factory_ == address(0)) {
            revert ZeroAddress();
        }

        factory = factory_;
    }

    function deploy(
        KimiMintToken.LaunchConfig calldata launchConfig,
        KimiMintToken.TaxConfig calldata taxConfig,
        address initialHolder,
        bytes32 salt
    )
        external
        returns (address token)
    {
        if (msg.sender != factory) {
            revert NotFactory();
        }

        token = address(new KimiMintToken{ salt: salt }(launchConfig, taxConfig, initialHolder));
    }
}

contract KimiMintVaultDeployer is Ownable {
    address public factory;

    error FactoryAlreadySet();
    error NotFactory();
    error ZeroAddress();

    constructor() Ownable(msg.sender) {}

    function setFactory(address factory_) external onlyOwner {
        if (factory != address(0)) {
            revert FactoryAlreadySet();
        }
        if (factory_ == address(0)) {
            revert ZeroAddress();
        }

        factory = factory_;
    }

    function deploy(
        address token,
        address liquidityRouter,
        address paymentToken,
        address owner,
        address receiver,
        uint256 totalSupply,
        uint256 totalMints,
        uint256 mintPrice,
        uint256 maxMintPerWallet,
        uint256 whitelistMintLimit,
        bool whitelistEnabled,
        bytes32 salt
    )
        external
        returns (address vault)
    {
        if (msg.sender != factory) {
            revert NotFactory();
        }

        vault = address(new KimiMintVault{ salt: salt }(
            token,
            liquidityRouter,
            paymentToken,
            owner,
            receiver,
            totalSupply,
            totalMints,
            mintPrice,
            maxMintPerWallet,
            whitelistMintLimit,
            whitelistEnabled
        ));
    }
}

contracts/mint/KimiMintAuditRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract KimiMintAuditRegistry is Ownable, ReentrancyGuard {
    enum AuditorStatus {
        None,
        Applied,
        Approved
    }

    enum RiskLevel {
        Low,
        Medium,
        High,
        Critical
    }

    struct AuditorProfile {
        AuditorStatus status;
        string profileUri;
        uint64 appliedAt;
        uint64 approvedAt;
        uint64 reviewCount;
    }

    struct ProjectReview {
        address auditor;
        address projectToken;
        uint8 score;
        RiskLevel riskLevel;
        string reportUri;
        uint64 updatedAt;
    }

    mapping(address auditor => AuditorProfile profile) public auditors;
    mapping(address projectToken => mapping(address auditor => ProjectReview review)) private _reviews;
    mapping(address projectToken => address[] auditors) private _projectReviewers;
    mapping(address auditor => address[] projectTokens) private _auditorProjects;
    mapping(address auditor => bool exists) private _auditorIndexed;
    mapping(address projectToken => bool exists) private _reviewedProjectIndexed;

    address[] public allAuditors;
    address[] public allReviewedProjects;

    error InvalidAddress();
    error InvalidProfile();
    error InvalidReview();
    error NotApprovedAuditor();

    event AuditorApplied(address indexed auditor, string profileUri);
    event AuditorStatusUpdated(address indexed auditor, AuditorStatus status);
    event ProjectReviewed(
        address indexed projectToken,
        address indexed auditor,
        uint8 score,
        RiskLevel riskLevel,
        string reportUri
    );

    constructor() Ownable(msg.sender) {}

    function applyAuditor(string calldata profileUri) external nonReentrant {
        if (bytes(profileUri).length == 0) {
            revert InvalidProfile();
        }

        AuditorProfile storage profile = auditors[msg.sender];
        if (!_auditorIndexed[msg.sender]) {
            _auditorIndexed[msg.sender] = true;
            allAuditors.push(msg.sender);
        }

        if (profile.status != AuditorStatus.Approved) {
            profile.status = AuditorStatus.Applied;
        }

        profile.profileUri = profileUri;
        if (profile.appliedAt == 0) {
            profile.appliedAt = uint64(block.timestamp);
        }

        emit AuditorApplied(msg.sender, profileUri);
    }

    function setAuditorStatus(address auditor, AuditorStatus status) external onlyOwner {
        if (auditor == address(0)) {
            revert InvalidAddress();
        }

        AuditorProfile storage profile = auditors[auditor];
        if (!_auditorIndexed[auditor]) {
            _auditorIndexed[auditor] = true;
            allAuditors.push(auditor);
            profile.appliedAt = uint64(block.timestamp);
        }

        profile.status = status;
        if (status == AuditorStatus.Approved && profile.approvedAt == 0) {
            profile.approvedAt = uint64(block.timestamp);
        }

        emit AuditorStatusUpdated(auditor, status);
    }

    function submitReview(
        address projectToken,
        uint8 score,
        RiskLevel riskLevel,
        string calldata reportUri
    )
        external
        nonReentrant
        onlyApprovedAuditor
    {
        if (projectToken == address(0)) {
            revert InvalidAddress();
        }
        if (score > 100 || uint8(riskLevel) > uint8(RiskLevel.Critical) || bytes(reportUri).length == 0) {
            revert InvalidReview();
        }

        ProjectReview storage review = _reviews[projectToken][msg.sender];
        bool firstReview = review.auditor == address(0);

        if (firstReview) {
            _projectReviewers[projectToken].push(msg.sender);
            _auditorProjects[msg.sender].push(projectToken);
            auditors[msg.sender].reviewCount += 1;
        }
        if (!_reviewedProjectIndexed[projectToken]) {
            _reviewedProjectIndexed[projectToken] = true;
            allReviewedProjects.push(projectToken);
        }

        review.auditor = msg.sender;
        review.projectToken = projectToken;
        review.score = score;
        review.riskLevel = riskLevel;
        review.reportUri = reportUri;
        review.updatedAt = uint64(block.timestamp);

        emit ProjectReviewed(projectToken, msg.sender, score, riskLevel, reportUri);
    }

    function allAuditorsLength() external view returns (uint256) {
        return allAuditors.length;
    }

    function allReviewedProjectsLength() external view returns (uint256) {
        return allReviewedProjects.length;
    }

    function projectReviewersLength(address projectToken) external view returns (uint256) {
        return _projectReviewers[projectToken].length;
    }

    function getProjectReview(address projectToken, address auditor)
        external
        view
        returns (ProjectReview memory)
    {
        return _reviews[projectToken][auditor];
    }

    function getProjectReviews(address projectToken)
        external
        view
        returns (ProjectReview[] memory projectReviews)
    {
        address[] storage reviewers = _projectReviewers[projectToken];
        projectReviews = new ProjectReview[](reviewers.length);

        for (uint256 i = 0; i < reviewers.length; i++) {
            projectReviews[i] = _reviews[projectToken][reviewers[i]];
        }
    }

    function getAuditorProjects(address auditor) external view returns (address[] memory) {
        return _auditorProjects[auditor];
    }

    modifier onlyApprovedAuditor() {
        if (auditors[msg.sender].status != AuditorStatus.Approved) {
            revert NotApprovedAuditor();
        }
        _;
    }
}

